#define DCAN_DMA1CTL_TRIGSEL_M                                       0x0000000CU
#define DCAN_DMA1CTL_TRIGSEL_S                                       2U
#define DCAN_DMA1CTL_TRIGSEL_TX_OTO_TRIG                             0x00000000U
